const fs=require('fs'),path=require('path');
const src='C:/WorkSpace/Seonghanji/docs/02-characters';
const out=__dirname;
const clean=s=>s.replace(/\*\*/g,'').trim();
const roles={제:'제독',강:'강습',파:'파일럿',참:'참모',관:'관료'};
const records=[];
function rows(file,accept,parse){let major='',minor='',header=[];fs.readFileSync(path.join(src,file),'utf8').split(/\r?\n/).forEach((line,i)=>{if(line.startsWith('## '))major=line.slice(3);if(line.startsWith('### '))minor=line.slice(4);if(!line.startsWith('|'))return;let c=line.split('|').slice(1,-1).map(clean);if(c.includes('인물')&&c.includes('통솔')){header=c;return;}if(accept(c,major,header)){parse(Object.fromEntries(header.map((k,j)=>[k,c[j]])),major,minor,i+1,file);}})}
const details=new Map();
fs.readFileSync(path.join(src,'generals-150.md'),'utf8').split(/\r?\n/).forEach(line=>{if(!line.startsWith('|'))return;let c=line.split('|').slice(1,-1).map(clean);let g=c.findIndex(x=>/^(특|[123])급$/.test(x));if(g>0&&/^[제강파참관]$/.test(c[g+1]||'')){let name=/^\d+$/.test(c[0])?c[1]:c[0];details.set(name,{classes:[c[g+1],c[g+2]].filter(x=>roles[x]).join('·'),trait:c[g+3]||''});}});
function add(o,major,minor,line,file,tier){let name=o['인물'];let faction=major.replace(/^\d+\. /,'').replace(/ \(.*/,'');if(tier==='O'&&major.startsWith('4.'))faction=minor.replace(/^\d+\.\d+ /,'').replace(/ \(.*/,'');if(tier==='F')faction=minor.replace(/^§[\d.]+ /,'').replace(/ \(.*/,'');let d=details.get(name)||{};let cls=o['클래스']||d.classes||'관';let names=name.includes('·')?name.split('·'): [name];if(name==='관흥의 형제 관색')names=['관색'];if(name==='육개의 종형 육모')names=['육모'];if(name==='유봉의 부장 맹달 계열')names=[];if(name==='언기·소륵·차사왕')names=['언기왕','소륵왕','차사왕'];for(let n of names){records.push({name:n,sourceName:name,tier,faction,classes:cls,role:cls.split('·').map(x=>roles[x]||x).join(' · '),trait:o['간이 특성']||o['특성']||d.trait||'',era:o['시대']||o['활동기']||'',stats:Object.fromEntries(['통솔','무력','지력','정치','매력'].map(k=>[k,Number(o[k])])),source:file,line});}}
rows('generals-stats.md',(c,m,h)=>/^[2345]\. /.test(m)&&c.length===7&&/^(特|특|[123])급$/.test(c[1]),(o,m,n,l,f)=>add(o,m,n,l,f,'G'));
rows('officers-256.md',(c,m,h)=>/^[1234]\. /.test(m)&&h.includes('간이 특성')&&c.length===h.length&&c.some(x=>/^[123]급$/.test(x)),(o,m,n,l,f)=>add(o,m,n,l,f,'O'));
rows('foreign-90-stats.md',(c,m,h)=>m==='2. 스탯표'&&h.includes('활동기')&&c.length===10&&/^(③|원수급)$/.test(c[2]),(o,m,n,l,f)=>add(o,m,n,l,f,'F'));
const seen=new Map(),duplicates=[];const unique=records.filter(o=>{if(seen.has(o.name)){duplicates.push({name:o.name,kept:seen.get(o.name).source,removed:o.source});return false;}seen.set(o.name,o);return true;});
const female=new Set('변씨 채염 곽여왕 신헌영 견희 장춘화 황월영 감부인 미부인 오국태 대교 소교 손상향 손노반 초선 왕이 축융 손노육 추씨 우씨왕후'.split(' '));
const special={하후돈:'one blind eye with a discreet cybernetic prosthetic, rugged face',관우:'long flowing black beard, long face, dignified stern expression, massive shoulders',장비:'powerful broad face, thick black beard, fierce eyes, huge muscular build',제갈량:'slender thoughtful face, elegant short moustache and beard, calm analytical expression',황충:'elderly veteran with grey hair and beard, alert eyes',여포:'tall powerful handsome warrior, severe confident expression',주유:'refined handsome young commander, clean shaven, poised expression',손책:'athletic charismatic youthful commander, energetic confident gaze',조조:'short dark hair streaked with grey, penetrating narrow eyes, trimmed moustache and short beard, calculating composed authority'};
for(let i=0;i<unique.length;i++){let o=unique[i];o.id='SHJ-'+o.tier+String(unique.slice(0,i+1).filter(x=>x.tier===o.tier).length).padStart(3,'0');o.tags=[o.id,o.name,o.faction,o.role];o.filename=o.id+'_'+o.name.replace(/[<>:"/\\|?*]/g,'_')+'.png';o.status='pending';let age=32+(i*7%27);let gender=female.has(o.name)?'woman':'man';let heritage=o.faction.includes('서방')?'culturally appropriate Mediterranean, West Asian or South Asian human appearance according to this named historical person':'East or Central Asian human appearance appropriate to the named person';let uniform=o.classes.startsWith('강')?'heavy functional powered boarding armor':o.classes.startsWith('파')?'compact flight suit with armored collar':o.classes.startsWith('참')?'tailored tactical analysis officer uniform':o.classes.startsWith('관')?'tailored civil command uniform':'structured naval admiral uniform';o.prompt=`Use case: stylized-concept. ONE standalone 4:5 photoreal cinematic SF character portrait card. Reference image is style and composition only: realistic textured human chest-up portrait, dark softly blurred starship bridge with sparse teal instruments, restrained cinematic light, thin teal-grey rectangular border. Subject: ${o.name}, ${o.faction}, ${o.role}, an original adult ${gender}, approximately ${age} years old, ${heritage}. ${special[o.name]||'Distinct individual facial structure and hairstyle, realistic skin and restrained expression'}. Source characterization: ${o.trait}. Translate personality and role into the facial expression and functional costume, without printing stats or inventing historical events. Costume: ${uniform}, charcoal muted metal with subtle faction piping and sparse antique gold trim. Whole head visible, chest-up centered, no hands. Low-saturation military political science fiction, no aliens, magic, celebrity likeness, franchise designs, historical robes, exaggerated neon or fake lettering. Bottom dark name panel, exact legible Korean text: large '${o.name}', smaller '${o.faction} | ${o.role}', tags '#${o.id} #${o.name}'. ONE portrait, no grid. Historical attributes without documented physical description are creative visual interpretation.`;}
fs.mkdirSync(path.join(out,'images'),{recursive:true});
fs.writeFileSync(path.join(out,'manifest.json'),JSON.stringify({sourceRoot:src,created:'2026-10-13',total:unique.length,counts:Object.fromEntries(['G','O','F'].map(t=>[t,unique.filter(x=>x.tier===t).length])),duplicates,notes:['Composite named rows split into individual portraits.','Unnamed generic Meng Da subordinate row omitted; named Meng Da retained.','Physical appearance is creative interpretation, not documented fact.'],records:unique},null,2));
fs.writeFileSync(path.join(out,'prompts.jsonl'),unique.map(o=>JSON.stringify({id:o.id,name:o.name,prompt:o.prompt})).join('\n'));
console.log(JSON.stringify({total:unique.length,counts:Object.fromEntries(['G','O','F'].map(t=>[t,unique.filter(x=>x.tier===t).length])),duplicates},null,2));

const fs=require('fs'),path=require('path');
const p=path.join(__dirname,'prepare.cjs');let s=fs.readFileSync(p,'utf8');
s=s.replace("name.includes('·')?name.split('·'): [name]","name.includes('·')&&!name.includes('(')?name.split('·'): [name]");
const start=s.indexOf('const seen=new Map()'),end=s.indexOf('const female=',start);
s=s.slice(0,start)+"const seen=new Map(),duplicates=[];const unique=records.filter(o=>{const k=o.name+'|'+o.faction;if(o.tier==='F'&&['여개','왕항'].includes(o.name)){duplicates.push({name:o.name,removed:o.source,reason:'Same Shu officer already included'});return false;}if(seen.has(k)){duplicates.push({name:o.name,removed:o.source});return false;}seen.set(k,o);return true;});\n"+s.slice(end);
fs.writeFileSync(p,s);

const fs=require('fs'),path=require('path');
const dir=__dirname,mp=path.join(dir,'manifest.json'),m=JSON.parse(fs.readFileSync(mp,'utf8'));
const [id,source]=process.argv.slice(2),r=m.records.find(x=>x.id===id);if(!r)throw Error('Unknown id');
const dest=path.join(dir,'images',r.filename);if(source)fs.copyFileSync(source,dest);if(!fs.existsSync(dest))throw Error('Missing image');
r.status='generated';r.generator='built-in image_gen';r.generatedSource=source||r.generatedSource;r.bytes=fs.statSync(dest).size;
fs.writeFileSync(mp,JSON.stringify(m,null,2));
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const completed=m.records.filter(x=>x.status==='generated');
const cards=completed.map(x=>`<article data-search="${esc(x.tags.join(' '))}"><img loading="lazy" src="images/${encodeURIComponent(x.filename)}" alt="${esc(x.name)}"><h2>${esc(x.name)}</h2><p>${esc(x.faction)} · ${esc(x.role)}</p><small>${esc(x.tags.map(t=>'#'+t).join(' '))}</small></article>`).join('');
fs.writeFileSync(path.join(dir,'index.html'),`<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>성한지 장수 초상</title><style>body{background:#09141b;color:#d9e7ee;font:16px system-ui;margin:32px}input{width:min(700px,90%);padding:12px;background:#182a34;color:white;border:1px solid #526d7b}main{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:20px;margin-top:24px}article{background:#12212a;padding:12px;border:1px solid #3d5865}img{width:100%;height:auto}h2{margin:12px 0 4px}p,small{color:#9cbbc9}[hidden]{display:none}</style><h1>성한지 장수 초상</h1><p>생성 완료 ${completed.length} / ${m.total}명 · 이름·소속·역할·ID로 검색</p><input aria-label="장수 검색" placeholder="장수 이름 또는 태그 검색" oninput="document.querySelectorAll('article').forEach(e=>e.hidden=!e.dataset.search.toLowerCase().includes(this.value.toLowerCase()))"><main>${cards}</main></html>`);
console.log(`${r.id} ${r.name} saved; ${completed.length}/${m.total}`);

