Add-Type -AssemblyName System.Drawing
$manifestPath=Join-Path $PSScriptRoot 'manifest.json'
$manifest=Get-Content -Raw -Encoding UTF8 -LiteralPath $manifestPath | ConvertFrom-Json
$completed=@($manifest.records | Where-Object {$_.status -eq 'generated'})
$errors=@()
foreach($record in $completed){
 $imagePath=Join-Path (Join-Path $PSScriptRoot 'images') $record.filename
 if(-not (Test-Path -LiteralPath $imagePath)){ $errors+='Missing: '+$record.id;continue }
 $portraitImage=[System.Drawing.Image]::FromFile($imagePath)
 try {if($portraitImage.Width -ne 561 -or $portraitImage.Height -ne 701){$errors+='Wrong dimensions: '+$record.id}}finally{$portraitImage.Dispose()}
}
$tags=Get-Content -Raw -Encoding UTF8 -LiteralPath (Join-Path $PSScriptRoot 'tags.json') | ConvertFrom-Json
if(@($tags).Count -ne $manifest.total){$errors+='Metadata count mismatch'}
Write-Output ('Verified dimensions and metadata: {0}/{1} portraits generated' -f $completed.Count,$manifest.total)
if($errors.Count){$errors | Write-Output;exit 1}

const fs=require('fs'),path=require('path');const p=path.join(__dirname,'manifest.json'),m=JSON.parse(fs.readFileSync(p,'utf8'));
const shapes=['broad square face with heavy jaw','long narrow face with pointed chin','round face with broad cheeks','angular diamond face with high cheekbones','oval face with a prominent straight nose','wide face with a low brow and broad nose','slim elongated face with an aquiline nose','compact face with deep-set eyes'];
const hair=['very short cropped hair','neatly combed side-parted hair','short wavy hair','receding hairline and cropped sides','swept-back medium-length hair','shaved head','thick curly short hair','close military buzz cut'];
const beards=['clean-shaven face','short full beard','thin moustache and small goatee','thick moustache, shaved chin','neatly trimmed salt-and-pepper beard','short stubble','long narrow grey beard','broad full beard with grey streaks'];
const womenHair=['short straight bob','close cropped hair','long hair tied in a low ponytail','neatly braided hair','shoulder-length wavy hair','swept-back hair in a tight bun'];
for(let i=0;i<m.records.length;i++){const r=m.records[i];if(r.status!=='pending'||r.castingSpec)continue;const female=r.prompt.includes('adult woman');r.castingSpec=`Unique individual casting: ${shapes[i%shapes.length]}, ${female?womenHair[(i*5)%womenHair.length]:hair[(i*3)%hair.length]+', '+beards[(Math.floor(i/3)+i)%beards.length]}. Use a clearly different facial identity from other portraits. Reference is lighting and rendering style ONLY; never reuse its actor's face. Physical appearance is artistic interpretation.`;r.prompt+=' '+r.castingSpec;}
fs.writeFileSync(p,JSON.stringify(m,null,2));fs.writeFileSync(path.join(__dirname,'prompts.jsonl'),m.records.map(r=>JSON.stringify({id:r.id,name:r.name,prompt:r.prompt})).join('\n'));console.log('Individual casting constraints added to pending portraits.');

const fs=require('fs'),path=require('path');const p=path.join(__dirname,'manifest.json'),m=JSON.parse(fs.readFileSync(p,'utf8'));
const castings=[
 ['동아시아계','East Asian human, medium-light skin'],
 ['아프리카계','Black human of African descent, deep brown skin'],
 ['남아시아계','South Asian human, warm brown skin'],
 ['유럽계','White human of European descent, fair skin'],
 ['동남아시아계','Southeast Asian human, tan skin'],
 ['중동·북아프리카계','Middle Eastern or North African human, olive skin'],
 ['라틴아메리카계','Latino human with mixed heritage, medium brown skin'],
 ['태평양제도계','Pacific Islander human, warm tan-brown skin'],
 ['북미원주민계','Indigenous North American human, medium copper-brown skin'],
 ['혼혈','human with mixed African and East Asian heritage, medium-dark skin']
];
for(let i=0;i<m.records.length;i++){
 const r=m.records[i];if(r.status!=='pending'){r.visualCasting={label:'동아시아계',fictionalInterpretation:true};continue;}
 const c=castings[(i*7+3)%castings.length];r.visualCasting={label:c[0],description:c[1],fictionalInterpretation:true};
 r.prompt=r.prompt.replace('East or Central Asian human appearance appropriate to the named person',c[1]).replace('culturally appropriate Mediterranean, West Asian or South Asian human appearance according to this named historical person',c[1]);
 r.prompt+=` Multiethnic SF casting direction: ${c[1]}. Historical name and documented gameplay role are retained, while ancestry is a fictional future-world visual reinterpretation. Distinct respectful natural human face, no ethnic caricatures, no ethnic costumes or stereotypes. Characters of every background can hold any faction, authority level or role.`;
 r.tags=[...r.tags.filter(t=>!castings.some(c=>c[0]===t)),c[0]];
}
m.imageSpecification.diverseHumanCasting=true;m.imageSpecification.ancestryIsFictionalInterpretation=true;
fs.writeFileSync(p,JSON.stringify(m,null,2));fs.writeFileSync(path.join(__dirname,'prompts.jsonl'),m.records.map(r=>JSON.stringify({id:r.id,name:r.name,prompt:r.prompt})).join('\n'));
require('./export-tags.cjs');
console.log(JSON.stringify({completed:m.records.filter(r=>r.status==='generated').length,total:m.total,pending:m.records.filter(r=>r.status==='pending').length,castings:castings.map(c=>c[0])}));

const fs=require('fs'),path=require('path');const p=path.join(__dirname,'manifest.json'),m=JSON.parse(fs.readFileSync(p,'utf8'));let count=0;
for(const r of m.records){if(!r.prompt.includes('adult woman'))continue;count++;r.visualCasting={...r.visualCasting,beautyDirection:'아름다운 성인 여성'};r.prompt+=' Female portrait requirement: a strikingly beautiful adult woman, harmonious facial proportions, expressive eyes, elegant natural features and polished grooming, photoreal healthy skin retaining natural texture. Give her an individual attractive face appropriate to her assigned multiethnic casting and age. Retain her commanding presence, practical military or civil uniform, authority and documented role. No sexualized pose or revealing outfit.';}
m.imageSpecification.femaleBeautyDirection='All female characters are beautiful adult women';
fs.writeFileSync(p,JSON.stringify(m,null,2));fs.writeFileSync(path.join(__dirname,'prompts.jsonl'),m.records.map(r=>JSON.stringify({id:r.id,name:r.name,prompt:r.prompt})).join('\n'));require('./export-tags.cjs');console.log(JSON.stringify({femalePortraits:count,total:m.total}));

const fs=require('fs'),path=require('path');
const p=path.join(__dirname,'manifest.json'),m=JSON.parse(fs.readFileSync(p,'utf8'));
const choices=[['동아시아계','East Asian human, medium-light skin'],['유럽계','Western European human, fair skin'],['동남아시아계','Southeast Asian human, tan skin']];
const labels=['동아시아계','아프리카계','남아시아계','유럽계','동남아시아계','중동·북아프리카계','라틴아메리카계','태평양제도계','북미원주민계','혼혈'];
let i=0;
for(const r of m.records){
 if(r.status!=='pending')continue;
 const slot=(i++*7)%20,c=choices[slot<11?0:slot<19?1:2];
 const old=r.visualCasting?.description;
 if(!old||!r.prompt.includes(old))throw Error('Missing casting description: '+r.id);
 r.prompt=r.prompt.split(old).join(c[1]);
 r.visualCasting={label:c[0],description:c[1],fictionalInterpretation:true};
 r.tags=[...r.tags.filter(t=>!labels.includes(t)),c[0]];
}
